import React, { useMemo } from 'react';
import { Cpu, Download, Zap, Circle } from 'lucide-react';

const formatBytes = (bytes) => {
  if (!bytes || bytes === 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(1024));
  return `${(bytes / Math.pow(1024, i)).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
};

const formatModelName = (name) => {
  if (!name) return 'Unknown model';
  return name.replace(/\.(bin|gguf)$/i, '');
};

const SttStatusBar = ({
  sttStatus = null,
  modelDownloadProgress = {},
  backendInstallProgress = {}
}) => {
  const isRunning = sttStatus?.nativeReady === true;
  const isInferring = sttStatus?.inferenceRunning === true;
  const modelName = isRunning ? formatModelName(sttStatus?.modelDisplayName) : 'whisper-small';
  const backend = sttStatus?.activeBackend?.toUpperCase() || 'WEBGPU';
  const rtf = sttStatus?.realtimeFactor;

  const activeDownload = useMemo(() => {
    const backendDownload = Object.values(backendInstallProgress).find(
      (progress) => ['starting', 'download', 'extract'].includes(progress?.phase)
    );
    if (backendDownload) {
      return {
        ...backendDownload,
        displayName: `${backendDownload.backendId?.toUpperCase()} backend`,
        action: 'Installing',
        downloadedBytes: backendDownload.receivedBytes ?? backendDownload.extractedBytes
      };
    }
    const modelDownload = Object.values(modelDownloadProgress).find(
      (p) => p?.state === 'starting' || p?.state === 'downloading'
    );
    return modelDownload ? { ...modelDownload, action: 'Downloading', displayName: formatModelName(modelDownload.modelId) } : null;
  }, [backendInstallProgress, modelDownloadProgress]);

  const nativeStarting = sttStatus?.status === 'starting';
  const statusLabel = !sttStatus
    ? 'Initializing…'
    : isRunning
      ? (isInferring ? 'Inferring' : 'Idle')
      : nativeStarting
        ? 'Starting native…'
        : 'WebGPU fallback';

  const statusColor = !sttStatus
    ? 'bg-gray-500'
    : isRunning
      ? (isInferring ? 'bg-amber-400' : 'bg-emerald-400')
      : nativeStarting ? 'bg-gray-500' : 'bg-blue-400';

  const statusPulse = isInferring ? 'animate-pulse' : '';

  if (activeDownload) {
    return (
      <div className="shrink-0 border-t border-white/10 bg-white/[0.03] px-4 py-3 space-y-2">
        <div className="flex items-center gap-2 text-[11px] font-bold text-blue-200/80">
          <Download size={14} className="text-blue-400 animate-bounce" />
          <span>{activeDownload.action} {activeDownload.displayName}</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex-1 h-1.5 rounded-full bg-white/10 overflow-hidden">
            <div
              className="h-full rounded-full bg-gradient-to-r from-blue-500 to-blue-400 transition-all duration-300"
              style={{ width: `${activeDownload.percent || 0}%` }}
            />
          </div>
          <span className="text-[10px] font-bold text-gray-400 tabular-nums w-8 text-right">
            {activeDownload.percent || 0}%
          </span>
        </div>
        {activeDownload.downloadedBytes !== undefined && activeDownload.totalBytes > 0 && (
          <p className="text-[10px] text-gray-500 tabular-nums">
            {formatBytes(activeDownload.downloadedBytes)} / {formatBytes(activeDownload.totalBytes)}
          </p>
        )}
      </div>
    );
  }

  return (
    <div className="shrink-0 border-t border-white/10 bg-white/[0.03] px-4 py-3">
      <div className="flex items-center gap-3">
        {/* Model pill */}
        <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-white/[0.06] border border-white/10">
          {backend === 'VULKAN' || backend === 'CUDA' ? (
            <Zap size={11} className="text-purple-400" />
          ) : (
            <Cpu size={11} className="text-blue-400" />
          )}
          <span className="text-[10px] font-bold text-gray-200">{modelName}</span>
          <span className="text-[9px] font-black text-gray-500">{backend}</span>
        </div>

        {/* Status dot + label */}
        <div className="flex items-center gap-1.5">
          <div className={`w-2 h-2 rounded-full ${statusColor} ${statusPulse}`} />
          <span className="text-[10px] font-bold text-gray-400">{statusLabel}</span>
        </div>

        {/* RTF */}
        {rtf !== null && rtf !== undefined && (
          <div className="flex items-center gap-1 ml-auto">
            <Circle size={8} className="text-gray-600" />
            <span className="text-[10px] font-bold text-gray-500 tabular-nums">
              RTF {rtf.toFixed(2)}x
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

export default SttStatusBar;

import { CameraOff, MicOff, Pin, Shield, User } from 'lucide-react';
import { useEffect, useRef } from 'react';

const initialsFor = (name = 'Guest') => name.trim().split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase()).join('') || 'G';

const VideoView = ({
    stream,
    isMuted = true,
    isVideoOff = true,
    displayName,
    isLocal = false,
    isHost = false,
    pinned = false,
    onClick,
    className = ''
}) => {
    const videoRef = useRef(null);
    const compact = !pinned;

    useEffect(() => {
        if (videoRef.current && stream) {
            videoRef.current.srcObject = stream;
        }
    }, [stream]);

    return (
        <div
            onClick={onClick}
            className={`relative isolate max-h-full max-w-full overflow-hidden rounded-[2rem] border bg-slate-950 shadow-2xl [contain:layout_paint] transition duration-300 ${!pinned ? 'aspect-video' : 'h-full w-full'} ${pinned ? 'border-blue-400/25 shadow-blue-950/20' : 'border-white/10'} ${onClick ? 'cursor-pointer hover:border-blue-300/35 hover:brightness-110' : ''} ${className}`}
        >
            <div className="pointer-events-none absolute inset-0 z-10 rounded-[inherit] bg-gradient-to-b from-black/20 via-transparent to-black/55" />
            <div className="pointer-events-none absolute inset-0 rounded-[inherit] bg-[radial-gradient(circle_at_top_left,rgba(59,130,246,0.16),transparent_35%),radial-gradient(circle_at_bottom_right,rgba(124,58,237,0.14),transparent_35%)]" />

            <video
                ref={videoRef}
                autoPlay
                playsInline
                muted={isLocal}
                className={`block h-full w-full rounded-[inherit] transition duration-500 ${pinned ? 'object-contain' : 'object-cover'} ${isLocal ? 'mirror' : ''} ${isVideoOff ? 'opacity-0 scale-105 blur-xl' : 'opacity-100 scale-100 blur-0'}`}
            />

            <div className={`absolute z-20 flex max-w-[calc(100%-1.5rem)] flex-wrap justify-end gap-2 ${compact ? 'right-3 top-3' : 'right-4 top-4'}`}>
                {isHost && (
                    <span className={`inline-flex items-center gap-1.5 rounded-full border border-blue-300/25 bg-blue-500/75 font-black uppercase tracking-[0.16em] text-white backdrop-blur-xl ${compact ? 'px-2 py-1 text-[9px]' : 'px-3 py-1.5 text-[10px]'}`}>
                        <Shield size={compact ? 10 : 12} fill="currentColor" /> Host
                    </span>
                )}
                {pinned && (
                    <span className="inline-flex items-center gap-1.5 rounded-full border border-white/15 bg-white/10 px-3 py-1.5 text-[10px] font-black uppercase tracking-[0.16em] text-white backdrop-blur-xl">
                        <Pin size={12} fill="currentColor" className="text-blue-200" /> Pinned
                    </span>
                )}
            </div>

            {isVideoOff && (
                <div className={`absolute inset-0 z-10 flex min-h-0 flex-col items-center justify-center overflow-hidden text-center ${compact ? 'px-4 py-9' : 'px-6 py-16'}`}>
                    <div className={`relative ${compact ? '' : 'mb-5'}`}>
                        {!isMuted && <div className="absolute inset-0 scale-125 rounded-full bg-emerald-400/10 blur-xl" />}
                        <div className={`relative flex items-center justify-center rounded-full border border-white/10 bg-white/[0.05] text-slate-300 shadow-2xl ${compact ? 'size-14' : 'size-24 sm:size-28'}`}>
                            {displayName ? <span className={`${compact ? 'text-lg' : 'text-3xl'} font-black tracking-tight`}>{initialsFor(displayName)}</span> : <User size={compact ? 24 : 42} />}
                        </div>
                    </div>
                    {!compact && (
                        <>
                            <p className="max-w-full truncate text-base font-black text-white">{displayName || 'Guest'}{isLocal ? ' (you)' : ''}</p>
                            <div className="mt-3 inline-flex items-center gap-2 rounded-full border border-white/10 bg-black/25 px-3 py-1.5 text-[10px] font-black uppercase tracking-[0.18em] text-slate-400 backdrop-blur-md">
                                <CameraOff size={12} /> Camera off
                            </div>
                        </>
                    )}
                </div>
            )}

            <div className={`absolute z-20 flex items-end justify-between gap-2 ${compact ? 'bottom-3 left-3 right-3' : 'bottom-4 left-4 right-4'}`}>
                <div className={`min-w-0 max-w-[calc(100%-3rem)] rounded-2xl border border-white/10 bg-black/45 backdrop-blur-2xl ${compact ? 'px-2.5 py-1.5' : 'px-4 py-2.5'}`}>
                    <div className="flex min-w-0 items-center gap-2">
                        <span className={`shrink-0 rounded-full ${compact ? 'size-2' : 'size-2.5'} ${isMuted ? 'bg-red-400' : 'bg-emerald-300 shadow-[0_0_12px_rgba(110,231,183,0.5)]'}`} />
                        <span className={`min-w-0 truncate font-black uppercase tracking-[0.14em] text-white ${compact ? 'text-[10px]' : 'text-xs'}`}>
                            {displayName || 'Guest'} {isLocal && <span className="text-blue-300">(you)</span>}
                        </span>
                    </div>
                </div>

                {isMuted && (
                    <div className={`flex shrink-0 items-center justify-center rounded-2xl border border-red-400/25 bg-red-500/15 text-red-300 backdrop-blur-xl ${compact ? 'size-8' : 'size-11'}`}>
                        <MicOff size={compact ? 14 : 18} />
                    </div>
                )}
            </div>
        </div>
    );
};

export default VideoView;

import test from 'node:test';
import assert from 'node:assert/strict';
import { mergeCaptions } from '../src/utils/captions.js';

test('merges history with live captions in chronological order', () => {
  const live = [{
    captionId: 'caption-c',
    text: 'Live',
    createdAt: '2026-07-28T12:00:03.000Z'
  }];
  const history = [
    { captionId: 'caption-a', text: 'First', createdAt: '2026-07-28T12:00:01.000Z' },
    { captionId: 'caption-b', text: 'Second', createdAt: '2026-07-28T12:00:02.000Z' }
  ];

  assert.deepEqual(
    mergeCaptions(live, history).map((caption) => caption.captionId),
    ['caption-a', 'caption-b', 'caption-c']
  );
});

test('deduplicates history and live events by persisted caption id', () => {
  const current = [{ captionId: 'caption-a', text: 'Live value', speakerName: 'A' }];
  const history = [{ captionId: 'caption-a', text: 'Persisted value', createdAt: '2026-07-28T12:00:01.000Z' }];
  const result = mergeCaptions(current, history);

  assert.equal(result.length, 1);
  assert.equal(result[0].text, 'Persisted value');
  assert.equal(result[0].speakerName, 'A');
});

test('deduplicates legacy live events by utterance id', () => {
  const current = [{ meetingId: 'm', speakerId: 's', utteranceId: 'u', text: 'First' }];
  const incoming = [{ meetingId: 'm', speakerId: 's', utteranceId: 'u', text: 'Updated' }];

  assert.deepEqual(mergeCaptions(current, incoming), [{
    meetingId: 'm',
    speakerId: 's',
    utteranceId: 'u',
    text: 'Updated'
  }]);
});

test('does not collapse unidentified captions with identical content', () => {
  const caption = { speakerId: 's', text: 'Repeated' };
  assert.equal(mergeCaptions([caption], [caption]).length, 2);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {
  getActiveApiKey,
  getSelectedModelId,
  LLM_PROVIDERS,
  normalizeLlmConfig
} from '../src/config/llmModels.js';

test('creates balanced defaults for a new configuration', () => {
  const config = normalizeLlmConfig(null);

  assert.equal(config.provider, 'openai');
  assert.equal(config.models.openai, LLM_PROVIDERS.openai.defaultModel);
  assert.equal(config.models.anthropic, LLM_PROVIDERS.anthropic.defaultModel);
  assert.equal(config.models.deepseek, LLM_PROVIDERS.deepseek.defaultModel);
});

test('migrates a legacy single key to its selected provider', () => {
  const config = normalizeLlmConfig({ provider: 'anthropic', apiKey: 'legacy-key' });

  assert.equal(config.apiKeys.anthropic, 'legacy-key');
  assert.equal(config.apiKeys.openai, '');
  assert.equal(getActiveApiKey(config), 'legacy-key');
});

test('retains independent valid models and provider keys', () => {
  const config = normalizeLlmConfig({
    provider: 'deepseek',
    models: {
      openai: 'gpt-5.6-sol',
      anthropic: 'claude-opus-5',
      deepseek: 'deepseek-v4-pro'
    },
    apiKeys: {
      openai: 'openai-key',
      anthropic: 'anthropic-key',
      deepseek: 'deepseek-key'
    }
  });

  assert.equal(getSelectedModelId(config), 'deepseek-v4-pro');
  assert.equal(getActiveApiKey(config), 'deepseek-key');
  assert.equal(config.apiKeys.openai, 'openai-key');
});

test('replaces stale model IDs with provider defaults', () => {
  const config = normalizeLlmConfig({
    provider: 'openai',
    models: { openai: 'retired-model' }
  });

  assert.equal(getSelectedModelId(config), LLM_PROVIDERS.openai.defaultModel);
});
